import * as React from "react";

export type DiceTwoIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function DiceTwoIcon({ size = 20, ...props }: DiceTwoIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="5" y="5" width="14" height="14" rx="2.5" /><circle cx="9.5" cy="9.5" r="1.2" /><circle cx="14.5" cy="14.5" r="1.2" />
    </svg>
  );
}
